var ENT=[["Apache Lucene", "The Java search library underneath it all."], ["OpenSearch", "Community search and analytics suite."], ["Sphinx Search", "SQL-friendly full-text engine."], ["Tantivy", "A Rust Lucene-like search library."], ["Elasticsearch", "Distributed search engine combining inverted indexes with relevance ranking."], ["Apache Solr", "Mature Lucene-based search server with faceting and rich text analysis."], ["BM25", "The probabilistic ranking function behind modern full-text relevance."]];
